import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
add('外資淨買比','近N筆外資買賣超為正的日數占比高於門檻，下一開盤多一口；占比不再高於門檻就退出。','外資買賣超',['僅支援TX資料，外資買賣超日表第二欄>0算買入日，零與負值不算。每個N筆滾動窗計正日數/N，不按金額加權。','相鄰分鐘跨曆日最後一根查同日占比，嚴格>門檻目標+1，其他目標0；下一根open執行，同方向不加碼。'],['占比<=門檻於下筆open退出，沒有放空與價格停損。資料末筆close全平。','換倉事件平舊開新一口並continue，當根日界訊號略過。'],[cost,'日統計資料獨立讀入全檔，再按訊號日精確查找，找不到維持原部位；均值暖機段填0，不另跳過。'],['資料不夠N筆時計算工具可能先索引超界；門檻未限定0到1，負門檻可讓暖機0值也通過。','日界以曆日而非商品交易日處理，帶夜盤的訊號時刻需按資料範圍解讀。'],{'買賣N日':'近N個外資資料列的正買賣超日數占比，並非最近N個日曆日或總買入金額比。','買入日佔比':'0到1比例，嚴格高於才持多，等於也退出；未自動驗證範圍。'})
add('買賣超加黑K','外資平均買賣超與當日日K價差同時落在指定區間，收盤或夜盤首價進指定方向，下一日開盤退出。','買賣超與K棒',['僅支援TX，強制把商品最後時間改1500後重建日資料；以同合約13:50以前最後close作K棒，另存13:45附近新合約價與15:00附近價。','選當日以前或昨日以前的外資日均值，換成億元；金額最小<均值<金額最大且K棒最小<close−open<K棒最大才進一口，方向可多可空。'],['日盤模式以aux_price1標13:45進，夜盤模式以aux_price2標15:00進；次資料日open固定標08:45退出。每個日對完整開平，不持多天。'],[cost,'買賣超條件是N筆簡單平均，不是N日金額總和；K棒與入場價可不是同合約，結算日保留舊約K棒而以新約13:45附近價進。'],['四個區間端點全部不含等號；名稱雖黑K，但改上下界可允許紅K，方向也不限放空。','沒有15:00資料時aux_price2沿用之前收盤附近價，卻仍寫15:00時戳；時刻與價格不是必然同時。全域商品最後時間會被此策略改動。','當日以前選項假定當日日資料到進場時已可用；程式未檢查外資統計實際發布時間。'],{'策略方向':'固定每次作多或作空一口，不依黑K自動反向。','進場時間':'日盤1345用aux_price1，夜盤1500用aux_price2；夜盤缺價可沿日盤價，不代表真的在15:00成交。','可用買賣超':'當日以前取訊號日的均值，昨日以前取前一個日資料日；皆需外資表精確日期匹配。','均線天數':'外資買賣超金額的N筆簡單平均，非合計。','金額最大':'以億元計的平均買賣超上限，需嚴格小於。','金額最小':'以億元計的平均買賣超下限，需嚴格大於。','K棒最大':'同合約日close−open點數的上限，嚴格小於。','K棒最小':'日close−open下限，嚴格大於；上下界可自行改成紅K範圍。'})
add('結算前多','從合約日資料選結算前或新倉第N筆進場，搭配開倉以來漲跌及外資OI濾網，持有至結算或日線停損。','結算時序',['從第二個合約起，結算前模式取尾索引−N，新倉第N日取前合約末日對應到本約的第一筆索引+N。開盤進場用open標08:45，收盤用close標13:45。','需相對本約新倉第一日open漲達或跌達X%；方向另指定多／空，並不隨漲跌濾網變。可再要求前一資料日外資OI>=或<=指定口數。'],['預計本合約最後日close標13:45退出；若日low碰多損或日high碰空損，將退出改成停損價並標11:00。','停損掃描沒有break，所以多個日期到價會持續覆寫，最後取最後一次碰停損日，不是首次停損。'],[cost,'獨立載全合約日資料，不跑一般分鐘迴圈；只用開始／結束日期過濾進場日期，出場仍可到區間外結算日。','開盤進場從同日檢查日high/low，收盤進場從次資料日檢查；一個合約一輪一口。OI等號允許通過，不是名稱所說嚴格大於／小於。'],['停損成交一律線價，沒有不利跳空保護，11:00只是固定紀錄時刻，非由分鐘資料定位。','停止掃描直到合約末端且選最後一次觸價，會改寫真正風險發生日；報表不能當首次即時停損結果。','新倉N可為0或負數，仍須計算後索引>=0且<最後筆；N以資料筆數算，不是固定日曆天。'],{'策略方向':'合約每次固定作多或作空一口，與漲跌檢查方向獨立。','進場時間':'結算日前n天按合約日資料尾回推；新倉第n天按前約最後日定位再加N。','進場時間N':'資料列偏移，不是日曆天；新倉0可落舊約結算日對應列，負值再往前。','開收盤進場':'決定用選定日open或close，及當日是否已納入日高低停損檢查。','自開倉以來':'相對新倉第1日open，要求上漲X%或下跌X%，與最終交易方向獨立。','漲跌X':'相對新倉首open的百分比幅度，達等號通過。','外資未平倉':'皆可略過；要大於實作>=，要小於實作<=，以進場前一合約資料日OI為準。','未平倉口數':'OI口數門檻，非下單數量；僅OI濾網啟用且idx>0時檢查。','停損':'入場價加減%或點數，按商品tick Round；日high/low觸價後仍往後掃並取最後一次觸發。','開始日期':'只過濾預定合約進場日，不裁合約後面的退出日期。','結束日期':'只擋此日期之後進場，持倉仍可退出於區間外的合約尾日。'})
add('新低作多','單合約嚴格創M筆新低後等待P個資料日，以開盤買一口，容許多筆重疊，按分鐘停損或合約末日退出。','新低反彈',['選open、close或low嚴格低於先前M筆同欄才記新低索引；新低重現會重設等待起點。','距最近新低索引恰P筆時，未達總啟動口數及此合約停損次數上限，且前日均線條件通過，按當日open買一口並標08:45。'],['日low<=停損價才進分鐘搜尋；同約同曆日且ValidKBAR通過的第一筆open<=停損價才真的退出，成交當根open。日low碰到但抽樣open未碰就不退出。','合約資料掃到底後，所有剩餘一口以合約最後日close標13:30賣出；不作新月續倉。'],[cost,'各合約停損計數歸零，啟動項數代表未平一口數；本日先檢查可進，再檢查新低與既有停損，當日新低本身不會同根以P=0新增。','均線使用連續回測日收盤、不調換倉價差；前一日找不到均線日期時直接放行，而不是拒絕。'],['DoBackTestContract收到end但內迴圈未用它停止，會一路跑到合約尾；可能在指定回測結束之後繼續開倉／結算。','停損日資料與分鐘必須同合約同日；沒有當日分鐘就不承認日low已停損，後面仍續抱。','P=0時先測等待、後寫當日新低，無法當日立刻進；極端長度與負偏移缺完整索引防呆。'],{'新低計算':'用每日日open、close或low對前M筆同欄逐一比較，必須全部嚴格更低；等於不是新低。','突破M日低點':'不含當日的M筆回看窗，不是連續M日每天都創新低。','新低後P日進場':'距最近新低索引恰P筆進，新的新低重新計時；不是達P後每天都可進。','均線濾網':'按進場前一日連續日close對MA，以上含等號、以下含等號；該日缺資料直接通過。','均線天數':'前日收盤簡單平均窗，不作跨約價差回溯調整；只在濾網啟用時計算。','最多口數':'啟動中一口子項數的上限；每次進場一口，可多筆重疊。','停損':'每筆open減%或點數，原碼沒有Round；日low先預篩，再用同日抽樣分鐘open觸價才真停。','最多停損次數':'同一合約累積承認的停損筆數上限，到限後不再新進，已有倉仍可再停。','KBAR間隔ex':'只控制分鐘停損搜尋的相位，不控制合約日線新低與進場；可漏掉日low觸價。','開始交易時間':'只作分鐘ValidKBAR相位原點，固定08:45進場時戳與日線規則不由此限制。','結束日期':'外層只決定是否開始掃這個合約，內迴圈未用end截斷，可能繼續交易到合約最後日。'})
(S/'analysis/SuperDaily.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote Daily flows/settlement/newlow x4')
